    class Monitor:
        @pytest.hookimpl(trylast=True)
        def pytest_collection_modifyitems(self,session,config,items):
            ids=[i.nodeid for i in items]
            if args.mode=='browser':
                assert ids==spec['full_shard_ids'],'DIAGNOSTIC_ASSIGNMENT_OR_ORDER_MISMATCH'
                assert original_plugin.manifest['assignment_sha256']==spec['assignment_sha256']
                assert original_plugin.manifest['profile_sha256']==spec['profile_sha256']
                assert original_plugin.manifest['collected_count']==spec['collected_count']
                chosen=items[:len(spec['ids'])];omitted=items[len(spec['ids']):]
            else:
                expected=payload()['collections'][actual]
                assert len(ids)==expected['count'] and digest(ids)==expected['nodeids_sha256'],'DIAGNOSTIC_FULL_COLLECTION_MISMATCH'
                rows,_,_=runner['assignment'](items,6,runner['load_profile'](repo/'scripts/ci_test_file_costs_v1.json'),repo)
                assert runner['digest'](rows)==expected['assignment_sha256'],'DIAGNOSTIC_ASSIGNMENT_MISMATCH'
                wanted=set(spec['ids']);chosen=[i for i in items if i.nodeid in wanted];omitted=[i for i in items if i.nodeid not in wanted]
                assert [i.nodeid for i in chosen]==spec['ids'],'DIAGNOSTIC_SELECTED_IDENTITIES_OR_ORDER_MISMATCH'
            items[:]=chosen;config.hook.pytest_deselected(items=omitted)
            selected.extend(i.nodeid for i in items);assert selected==spec['ids']
            emit('collection_verified',count=len(selected),sha256=digest(selected),full_shard_assignment_verified=args.mode=='browser')
        @pytest.hookimpl(hookwrapper=True)
        def pytest_collection(self,session):
            t=time.perf_counter();state.update(phase='collection');yield
            phases.append(dict(phase='collection',seconds=time.perf_counter()-t));emit('collection_finished',seconds=time.perf_counter()-t)
        @pytest.hookimpl(hookwrapper=True)
        def pytest_fixture_setup(self,fixturedef,request):
            t=time.perf_counter();yield
            row=dict(name=fixturedef.argname,scope=fixturedef.scope,node=request.node.nodeid,seconds=time.perf_counter()-t)
            fixtures.append(row);emit('fixture',**row)
        @pytest.hookimpl(hookwrapper=True)
        def pytest_runtest_setup(self,item):
            state.update(phase='setup',node=item.nodeid);t=time.perf_counter();yield
            phases.append(dict(seconds=time.perf_counter()-t,**state))
        @pytest.hookimpl(hookwrapper=True)
        def pytest_runtest_call(self,item):
            state.update(phase='call',node=item.nodeid);t=time.perf_counter();yield
            phases.append(dict(seconds=time.perf_counter()-t,**state));emit('call_finished',node=item.nodeid,caches=caches())
        @pytest.hookimpl(hookwrapper=True)
        def pytest_runtest_teardown(self,item):
            state.update(phase='teardown',node=item.nodeid);t=time.perf_counter();yield
            phases.append(dict(seconds=time.perf_counter()-t,**state))
        def pytest_runtest_logreport(self,report):
            if report.when=='call' or (report.when=='setup' and report.outcome!='passed'):
                outcomes.append(dict(nodeid=report.nodeid,outcome=report.outcome,when=report.when));emit('outcome',**outcomes[-1])
    real_popen=subprocess.Popen;real_copy=shutil.copytree;depth=0
    class TimedGitProcess(real_popen):
        def __init__(self,*a,**kw):
            command=a[0] if a else kw.get('args');self._git=isinstance(command,(list,tuple)) and Path(str(command[0])).stem=='git'
            operation=str(command[1]) if self._git and len(command)>1 else 'OTHER'
            self._operation=operation if operation in {'init','config','add','commit','diff','rev-parse','show','ls-tree','cat-file','hash-object','checkout','commit-tree','merge-base','status','gc','log','write-tree','read-tree','update-index'} else 'OTHER'
            self._start=time.perf_counter();self._done=False;self._state=dict(state);super().__init__(*a,**kw)
        def record(self):
            if self._git and not self._done and self.returncode is not None:
                self._done=True;row=dict(operation=self._operation,seconds=time.perf_counter()-self._start,returncode=self.returncode,**self._state);git_rows.append(row)
        def communicate(self,*a,**kw):
            result=super().communicate(*a,**kw);self.record();return result
        def wait(self,*a,**kw):
            result=super().wait(*a,**kw);self.record();return result
    def copying(*a,**kw):
        nonlocal depth
        top=depth==0;depth+=1;t=time.perf_counter()
        try:return real_copy(*a,**kw)
        finally:
            depth-=1
            if top:copies.append(dict(seconds=time.perf_counter()-t,**state))
    profile=cProfile.Profile();profiled=args.mode!='browser';interrupted=False
    class Deadline(BaseException):pass
    def alarm(signum,frame):raise Deadline()
    supported_alarm=hasattr(signal,'SIGALRM')
    if supported_alarm:signal.signal(signal.SIGALRM,alarm);signal.alarm(args.seconds)
    if profiled:subprocess.Popen=TimedGitProcess;shutil.copytree=copying;profile.enable()
    thread=threading.Thread(target=heartbeat,daemon=True);thread.start()
    emit('start',revision=actual,mode=args.mode,seconds_limit=args.seconds,profiler=profiled,browser_subprocess_or_timeout_replaced=False,processes=process_snapshot())
    result=124;plugins=[Monitor()] if original_plugin is None else [original_plugin,Monitor()]
    targets=['tests']
    options=['-v',*targets,'--durations=30','--junitxml',str(output/'results.xml'),'--basetemp',str(output/'fixtures')]
    if args.validate_only:options.append('--collect-only')
