        stop.set();thread.join(timeout=3);subprocess.Popen=real_popen;shutil.copytree=real_copy
        report_started=time.perf_counter();functions=[]
        if profiled:
            profile.dump_stats(output/'profile.pstats')
            for (file,line,name),(primitive,calls,own,total,callers) in pstats.Stats(profile).stats.items():functions.append(dict(file=file,line=line,function=name,calls=calls,self_seconds=own,cumulative_seconds=total))
