def run(args):
    p=payload();case=p['cases'][args.mode];out=args.output.resolve();out.mkdir(parents=True,exist_ok=False)
    start=time.monotonic();deadline=start+1500;phases=[]
    expected_image=p['ubuntu_image_version'];actual_image=os.environ.get('ImageVersion','UNKNOWN')
    save(out/'environment-preflight.json',dict(expected_image=expected_image,actual_image=actual_image,python=sys.version,mode=args.mode,started_at=time.time()))
    if actual_image!=expected_image:raise SystemExit('DIAGNOSTIC_RUNNER_IMAGE_MISMATCH_NO_TESTS')
    labels=[('candidate',args.repo,case['candidate'])] if args.mode=='browser' else [('baseline',args.baseline,p['main']),('candidate',args.repo,case['candidate'])]
    for label,repo,rev in labels:
        remaining=int(deadline-time.monotonic())
        if remaining<30:save(out/'interrupted.json',dict(reason='SHARED1500SECOND_BUDGET',unstarted=label));return 124
        cmd=[sys.executable,'-B','-X','utf8',str(Path(__file__).resolve()),'--phase','--mode',args.mode,'--repo',str(repo.resolve()),'--output',str(out/label),'--revision',rev,'--seconds',str(remaining)]
        with (out/(label+'-stdout.log')).open('wb') as log:
            child=subprocess.Popen(cmd,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
            try:code=child.wait(timeout=remaining+20)
            except subprocess.TimeoutExpired:os.killpg(child.pid,signal.SIGKILL);child.wait();code=124
        phases.append(dict(label=label,exit_code=code,receipt=str(out/label/'receipt.json')))
        save(out/'phase-index.json',phases)
        if code:return code
    save(out/'completed.json',dict(status='COMPLETED_TARGETED_DIAGNOSTIC_ONLY',mode=args.mode,phases=phases,elapsed_seconds=time.monotonic()-start))
    return 0

def main():
    a=argparse.ArgumentParser();a.add_argument('--self-test',action='store_true');a.add_argument('--constraints',type=Path);a.add_argument('--phase',action='store_true');a.add_argument('--validate-only',action='store_true');a.add_argument('--mode',choices=['browser','margin2','margin5']);a.add_argument('--repo',type=Path);a.add_argument('--baseline',type=Path);a.add_argument('--output',type=Path);a.add_argument('--revision');a.add_argument('--seconds',type=int,default=1500);args=a.parse_args()
    if args.self_test:print(json.dumps(check_roundtrip()));return 0
    if args.constraints:
        args.constraints.write_text('\n'.join(payload()['constraints'])+'\n',encoding='utf-8');return 0
    return phase(args) if args.phase else run(args)
if __name__=='__main__':raise SystemExit(main())
